const markup="<div id=\"gv-pets-service\">\n<div class=\"scene\"><section class=\"window\" id=\"pg-window\" aria-labelledby=\"pg-title\">\n <header class=\"head\"><img id=\"pg-icon\" alt=\"\"><h2 id=\"pg-title\">Pets</h2><span class=\"owned-count\" id=\"pg-count\"></span><div class=\"active-chip\" aria-label=\"Companheiro equipado\"><b aria-hidden=\"true\">✓</b><span id=\"pg-active\"></span></div><button class=\"button close\" id=\"pg-close\" aria-label=\"Fechar Pets\">×</button></header>\n <nav class=\"filter-rail\" id=\"pg-filters\" aria-label=\"Filtrar por raridade\"></nav><label class=\"mobile-filter\">Raridade<select id=\"pg-filter-mobile\" aria-label=\"Filtrar pets por raridade\"></select></label>\n <div class=\"workspace\" id=\"pg-workspace\">\n  <section class=\"gallery\" aria-label=\"Coleção de companheiros\"><div class=\"pet-grid\" id=\"pg-grid\"></div><nav class=\"pager\" id=\"pg-pages\" aria-label=\"Páginas de pets\"><button class=\"button\" id=\"pg-prev\" aria-label=\"Página anterior de pets\">‹</button><span id=\"pg-page\"></span><button class=\"button\" id=\"pg-next\" aria-label=\"Próxima página de pets\">›</button></nav></section>\n  <aside class=\"inspector\" id=\"pg-inspector\" aria-label=\"Pet selecionado\"><div class=\"pet-heading\"><button class=\"button back\" id=\"pg-back\" aria-label=\"Voltar à coleção\">‹</button><h3 id=\"pg-name\"></h3><span class=\"rarity\" id=\"pg-rarity\"></span></div><button class=\"pet-stage\" id=\"pg-stage\" aria-label=\"Fazer carinho\"><img class=\"pedestal\" id=\"pg-pedestal\" alt=\"\"><span class=\"pet-character\" id=\"pg-character\"><img class=\"hero-model\" id=\"pg-model\" alt=\"\"><canvas class=\"hero-canvas\" id=\"pg-canvas\" aria-hidden=\"true\"></canvas></span><span class=\"stage-heart\" id=\"pg-stage-heart\" aria-hidden=\"true\">♥</span><span class=\"hearts\" id=\"pg-hearts\" aria-hidden=\"true\"></span></button><nav class=\"tabs\" aria-label=\"Informações do pet\"><button class=\"button\" id=\"pg-power-tab\" aria-pressed=\"true\">Poder</button><button class=\"button\" id=\"pg-bond-tab\" aria-pressed=\"false\">Vínculo</button></nav><div class=\"detail-body\"><section id=\"pg-power\"><div class=\"power-name\"><h4 id=\"pg-ability\"></h4><button class=\"button info\" id=\"pg-info\" aria-label=\"Ler descrição completa\" aria-expanded=\"false\">i</button></div><div id=\"pg-brief\"><strong class=\"power-number\" id=\"pg-number\"></strong><p class=\"power-note\" id=\"pg-note\"></p></div><p class=\"power-full\" id=\"pg-full\" hidden></p></section><section id=\"pg-bond\" hidden><p class=\"power-note\" id=\"pg-bond-unavailable\" hidden>Jornada indisponível. Seus dados foram preservados.</p><div class=\"needs\" id=\"pg-needs\"></div><div class=\"bond-done\" id=\"pg-bond-done\" hidden><b aria-hidden=\"true\">✓</b><span>Vínculo feito</span></div></section></div><div class=\"actions\"><button class=\"button\" id=\"pg-care\">♥ Cuidar</button><button class=\"button primary\" id=\"pg-equip\">Equipar</button></div></aside>\n </div><div class=\"empty\" id=\"pg-unavailable\" hidden><h3>Coleção indisponível</h3><p>Seus dados foram preservados.</p></div><div class=\"message\" id=\"pg-message\" role=\"alert\"></div><div class=\"sr\" id=\"pg-live\" aria-live=\"polite\"></div>\n</section></div></div>";

// Presentation only: the host owns current profile, transaction, persistence and audio.
