 const root=shadow.querySelector('#gv-pets-service'),$=id=>root.querySelector('#'+id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const tiers={all:'Todos',comum:'Comum',incomum:'Incomum',raro:'Raro',epico:'Épico',lendario:'Lendário'},motion=matchMedia('(prefers-reduced-motion: reduce)'),metadata=new Map(PET_ROSTER.map(p=>[p.id,p]));
