 const first=view();let filter=Object.hasOwn(tiers,initialUi.filter)?initialUi.filter:'all',selected=first.pets.some(p=>p.id===initialUi.selected)?initialUi.selected:first.activePet||first.pets.find(p=>p.owned)?.id||first.pets[0]?.id||null,capacity=root.clientWidth>=1000?8:6;
