 function renderGrid(focusId){const list=matching(),pages=Math.max(1,Math.ceil(list.length/capacity));page=Math.max(0,Math.min(page,pages-1));const visible=list.slice(page*capacity,(page+1)*capacity);if(!visible.some(p=>p.id===selected)){clearFeedback();selected=visible[0]?.id||null;full=false;tab=current()?.owned?'power':'bond';}const active=view().activePet;$('pg-grid').innerHTML=visible.map(p=>'<button class="pet-card cursor-interaction '+(!p.owned?'is-locked ':'')+(active===p.id?'is-equipped':'')+'" data-select="'+p.id+'" aria-pressed="'+(p.id===selected)+'" aria-label="Ver '+escape(p.name)+(p.owned?'':', bloqueado')+(active===p.id?', equipado':'')+'"><img src="'+petArtSpec(p.id).views.presentation.clips.pose.url+'" alt=""><span class="pet-name">'+escape(p.name)+'</span><span class="pet-meta">'+tiers[p.rarity]+(!p.owned?' · Bloqueado':'')+'</span>'+(active===p.id?'<b class="pet-check" aria-hidden="true">✓</b>':'')+(p.cared?'<span class="pet-cared" aria-label="Carinho registrado">♥</span>':'')+'</button>').join('');$('pg-pages').hidden=pages===1;$('pg-page').textContent=(page+1)+'/'+pages;$('pg-prev').disabled=page===0;$('pg-next').disabled=page===pages-1;if(focusId)root.querySelector('[data-select="'+focusId+'"]')?.focus();}
 function renderDetail(){const p=current();$('pg-inspector').hidden=!p;if(!p)return;$('pg-name').textContent=p.name;$('pg-rarity').textContent=tiers[p.rarity];$('pg-model').src=petArtSpec(p.id).views.presentation.clips.pose.url;$('pg-ability').textContent=p.power;const summary=brief[p.id]||[p.effect,''];$('pg-number').textContent=summary[0];$('pg-note').textContent=summary[1];$('pg-full').textContent=p.effect;$('pg-full').hidden=!full;$('pg-brief').hidden=full;$('pg-info').setAttribute('aria-expanded',String(full));$('pg-power').hidden=tab!=='power';$('pg-bond').hidden=tab!=='bond';$('pg-power-tab').setAttribute('aria-pressed',String(tab==='power'));$('pg-bond-tab').setAttribute('aria-pressed',String(tab==='bond'));$('pg-bond-done').hidden=!p.owned;$('pg-needs').hidden=p.owned||!p.journey.supported;$('pg-bond-unavailable').hidden=p.owned||p.journey.supported;$('pg-needs').innerHTML=p.journey.steps.map(s=>'<div class="need '+(s.done?'is-done':'')+'"><div class="need-row"><span>'+escape(s.label.replace(/ · \d+ \/ \d+$/,''))+'</span><b>'+Math.min(s.value,s.goal)+'/'+s.goal+'</b></div><div class="track" role="progressbar" aria-label="'+escape(s.label)+'" aria-valuemin="0" aria-valuemax="'+s.goal+'" aria-valuenow="'+Math.min(s.value,s.goal)+'"><span style="width:'+Math.min(100,s.value/s.goal*100)+'%"></span></div></div>').join('');$('pg-care').disabled=!p.care.available||readOnly();$('pg-care').setAttribute('aria-label','Cuidar de '+p.name);$('pg-stage').disabled=!p.care.available||readOnly();$('pg-stage').setAttribute('aria-label','Fazer carinho em '+p.name);$('pg-stage-heart').hidden=!p.owned;$('pg-equip').disabled=!p.equip.available||readOnly();$('pg-equip').textContent=!p.owned?'Bloqueado':p.equipped?'Desequipar':'Equipar';$('pg-equip').classList.toggle('remove',p.equipped);$('pg-equip').setAttribute('aria-pressed',String(p.equipped));$('pg-equip').setAttribute('aria-label',(!p.owned?'Bloqueado: ':p.equipped?'Desequipar ':'Equipar ')+p.name);}
 function render(){const v=view();$('pg-workspace').hidden=!v.supported;$('pg-unavailable').hidden=v.supported;$('pg-count').textContent=v.supported?v.pets.filter(p=>p.owned).length+'/'+v.pets.length:'—';$('pg-active').textContent=v.supported?(v.pets.find(p=>p.id===v.activePet)?.name||'Nenhum'):'—';$('pg-active').previousElementSibling.hidden=!v.activePet;root.querySelector('.active-chip').setAttribute('aria-label',v.activePet?'Companheiro equipado':'Nenhum companheiro equipado');root.dataset.detail=String(detail);root.dataset.soft=String(reduced());for(const b of root.querySelectorAll('[data-filter]')){b.disabled=!v.supported;b.setAttribute('aria-pressed',String(b.dataset.filter===filter));}$('pg-filter-mobile').disabled=!v.supported;$('pg-filter-mobile').value=filter;if(v.supported){renderGrid();renderDetail();}}
 function clearFeedback(){animations.forEach(a=>a.cancel());animations=[];$('pg-hearts').replaceChildren();}
 function impulse(care=false){clearFeedback();const stage=$('pg-character');if(!reduced())animations.push(stage.animate([{transform:'scale(.97)'},{transform:'scale(1.02)',offset:.65},{transform:'scale(1)'}],{duration:280,easing:'cubic-bezier(.2,.7,.2,1)'}));if(care&&!reduced()){$('pg-hearts').replaceChildren();for(let i=0;i<3;i++){const heart=document.createElement('span');heart.textContent='♥';$('pg-hearts').append(heart);const a=heart.animate([{opacity:0,transform:'translate(-50%,12px) scale(.6)'},{opacity:1,offset:.22},{opacity:0,transform:'translate('+((i-1)*32-50)+'px,-60px) scale(1.1)'}],{duration:850,delay:i*70,easing:'ease-out'});a.onfinish=()=>heart.remove();animations.push(a);}}}

 function act(action){const p=current();if(!p||disposed)return;clearFeedback();
  const result=onAction?.(action,p.id);if(!result?.ok){$('pg-message').textContent=result?.message||'Não foi possível salvar. Sua seleção anterior foi preservada.';$('pg-live').textContent='';renderDetail();return;}
  confirmButtonResult(root.ownerDocument,action==='care'?'craft':action==='remove'?'unset':'set');
  $('pg-message').textContent='';render();$('pg-live').textContent=action==='care'?'Carinho registrado para '+p.name+'.':action==='remove'?p.name+' desequipado.':p.name+' equipado.';impulse(action==='care');remember();
 }
 const filterOptions=Object.entries(tiers);$('pg-filters').innerHTML=filterOptions.map(([id,name])=>'<button class="button" data-filter="'+id+'" aria-pressed="'+(id==='all')+'">'+name+'</button>').join('');$('pg-filter-mobile').innerHTML=filterOptions.map(([id,name])=>'<option value="'+id+'">'+name+'</option>').join('');
