 $('pg-grid').onclick=e=>{const b=e.target.closest('[data-select]');if(!b)return;selected=b.dataset.select;tab=current().owned?'power':'bond';detail=true;full=false;time=0;$('pg-message').textContent='';renderGrid();renderDetail();root.dataset.detail='true';if(root.clientWidth<=650)$('pg-back').focus();else root.querySelector('[data-select="'+selected+'"]')?.focus({preventScroll:true});impulse();remember();};
 $('pg-prev').onclick=()=>{page--;full=false;renderGrid();renderDetail();if($('pg-prev').disabled)$('pg-next').focus();remember();};$('pg-next').onclick=()=>{page++;full=false;renderGrid();renderDetail();if($('pg-next').disabled)$('pg-prev').focus();remember();};$('pg-back').onclick=()=>{detail=false;root.dataset.detail='false';root.querySelector('[data-select="'+selected+'"]')?.focus();remember();};
 $('pg-power-tab').onclick=()=>{tab='power';renderDetail();remember();};$('pg-bond-tab').onclick=()=>{tab='bond';renderDetail();remember();};$('pg-info').onclick=()=>{full=!full;renderDetail();remember();};$('pg-care').onclick=()=>act('care');$('pg-stage').onclick=()=>act('care');$('pg-equip').onclick=()=>act(current()?.equipped?'remove':'equip');

 $('pg-close').onclick=onClose;
 root.addEventListener('keydown',e=>{if(e.key!=='Escape'||disposed)return;e.preventDefault();e.stopPropagation();if(root.clientWidth<=650&&detail){detail=false;root.dataset.detail='false';root.querySelector('[data-select="'+selected+'"]')?.focus();remember();}else onClose?.();});
 // Shadow controls do not reach the document click handler. Domain actions emit accept only after the host confirms.
 const command=e=>{const b=e.target.closest('button,select');if(b&&!b.disabled&&!disposed&&!['pg-care','pg-stage','pg-equip'].includes(b.id))onCommand();};root.addEventListener('click',command,true);
 $('pg-icon').src=petArtSpec('slime-friend').views.presentation.clips.pose.url;$('pg-pedestal').src=caretakerAssets.pedestal;
 function draw(now){if(disposed||!root.isConnected||!dialog.open)return;const paused=document.hidden||!view().supported;if(!paused&&!reduced())time+=Math.max(0,Math.min(.1,(now-last)/1000));last=now;
  const p=current(),stage=$('pg-stage');if(p&&!paused&&stage.getBoundingClientRect().width>0){const rig=petArtSpec(p.id)?.views.presentation;if(rig){const w=stage.clientWidth,h=stage.clientHeight,ped=$('pg-pedestal').getBoundingClientRect(),box=stage.getBoundingClientRect(),ground=ped.top+ped.height*.28-box.top,fit=petPortraitFit(rig,w,h,ground),fallback=$('pg-model');Object.assign(fallback.style,{left:fit.left+'px',top:fit.top+'px',width:fit.width+'px',height:fit.height+'px'});
   const canvas=$('pg-canvas'),dpr=Math.min(2,devicePixelRatio||1);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);const ok=drawPetArt(c,p.id,fit.x,fit.y,fit.k*rig.sourceScale,{time,reduced:reduced()}),pose=petIdlePose(p.id,time,reduced());canvas.dataset.frame=String(pose.frame);canvas.dataset.clip=pose.clip;canvas.dataset.ready=String(ok);fallback.style.visibility=ok?'hidden':'visible';
  }}request=requestAnimationFrame(draw);
 }
 function onMotion(){clearFeedback();render();}motion.addEventListener('change',onMotion);
 const resize=new ResizeObserver(()=>{if(disposed)return;const next=root.clientWidth>=1000?8:6;if(next!==capacity){const start=page*capacity;capacity=next;page=Math.floor(start/capacity);renderGrid();renderDetail();}});resize.observe(root);
