 render();if(readOnly())$('pg-message').textContent='Salvamento indisponível. Recarregue.';request=requestAnimationFrame(draw);queueMicrotask(()=>{if(dialog.open&&!disposed)$('pg-close').focus({preventScroll:true});});
 return ()=>{disposed=true;cancelAnimationFrame(request);resize.disconnect();motion.removeEventListener('change',onMotion);document.removeEventListener('visibilitychange',onVisibility);root.removeEventListener('click',command,true);clearFeedback();};
